#requires -version 5.1
<#
Hamraz One-Click Build / Doctor / Package runner

Purpose:
  Open this repository in VS Code, open a PowerShell terminal, and run this file.
  It handles the local build flow as far as the installed machine/toolchains allow.

Main commands:
  .\HAMRAZ_ONE_CLICK_BUILD.ps1 -Target Menu
  .\HAMRAZ_ONE_CLICK_BUILD.ps1 -Target Doctor
  .\HAMRAZ_ONE_CLICK_BUILD.ps1 -Target Verify
  .\HAMRAZ_ONE_CLICK_BUILD.ps1 -Target Web
  .\HAMRAZ_ONE_CLICK_BUILD.ps1 -Target Windows
  .\HAMRAZ_ONE_CLICK_BUILD.ps1 -Target Android -ApiUrl https://your-api.example
  .\HAMRAZ_ONE_CLICK_BUILD.ps1 -Target All -ApiUrl https://your-api.example
  .\HAMRAZ_ONE_CLICK_BUILD.ps1 -Target Clean

Design rules:
  1. Never invent an APK/AAB/EXE. An artifact is announced only if the file exists.
  2. Continue where useful for -Target All; a missing native toolchain does not erase
     successful web/static work.
  3. Keep all generated output under release/ plus transient state under
     .hamraz-oneclick/.
  4. Every external command is logged with its working directory and exit code.
  5. The script is standalone: it does not require another Hamraz PowerShell script.
  6. Production signing is not silently bypassed. Local package generation can be
     attempted, but distribution signing must use real credentials/certificates.
#>
[CmdletBinding()]
param(
  [ValidateSet('Menu','Doctor','Install','Verify','Web','Windows','Android','All','Clean')]
  [string]$Target='Menu',
  [string]$ApiUrl='',
  [switch]$SkipInstall,
  [switch]$VerboseLogs,
  [switch]$KeepBuilds
)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
$Root=Split-Path -Parent $MyInvocation.MyCommand.Path
$Root=(Resolve-Path $Root).Path
$Release=Join-Path $Root 'release'
$StateRoot=Join-Path $Root '.hamraz-oneclick'
$LogRoot=Join-Path $StateRoot 'logs'
$ToolRoot=Join-Path $StateRoot 'tools'
$RunId=Get-Date -Format 'yyyyMMdd-HHmmss'
$Log=Join-Path $LogRoot "run-$RunId.log"
$Report=Join-Path $Release "HAMRAZ_BUILD_REPORT-$RunId.json"
$script:ExitCode=0

function Ensure-Dir([string]$Path){ if(-not(Test-Path -LiteralPath $Path)){New-Item -ItemType Directory -Path $Path -Force|Out-Null} }
function Initialize-Runtime{ Ensure-Dir $Release; Ensure-Dir $StateRoot; Ensure-Dir $LogRoot; Ensure-Dir $ToolRoot; New-Item -ItemType File -Path $Log -Force|Out-Null }
function Log([string]$Message,[string]$Level='INFO'){
  $line='[{0}] [{1}] {2}'-f(Get-Date -Format 'yyyy-MM-dd HH:mm:ss'),$Level,$Message
  Add-Content -LiteralPath $Log -Value $line -Encoding UTF8
  switch($Level){'OK'{Write-Host $line -ForegroundColor Green}'WARN'{Write-Host $line -ForegroundColor Yellow}'ERROR'{Write-Host $line -ForegroundColor Red}'STEP'{Write-Host $line -ForegroundColor Cyan}default{Write-Host $line}}
}
function Section([string]$Name){Log ('='*78) 'STEP';Log $Name 'STEP';Log ('='*78) 'STEP'}
function Fail([string]$Message){Log $Message 'ERROR';throw $Message}
function Ok([string]$Message){Log $Message 'OK'}
function Warn([string]$Message){Log $Message 'WARN'}
function Command-Exists([string]$Name){return [bool](Get-Command $Name -ErrorAction SilentlyContinue)}
function Require([string]$Display,[string]$Command){if(-not(Command-Exists $Command)){Fail "$Display is missing from PATH: $Command"}}
function Read-Version([string]$Path){if(Test-Path $Path){return(Get-Content $Path -Raw).Trim()}return 'unknown'}
function Join-Root([string]$Relative){return(Join-Path $Root $Relative)}
function Has-File([string]$Relative){return(Test-Path -LiteralPath (Join-Root $Relative))}
function Write-State([hashtable]$Data){($Data|ConvertTo-Json -Depth 10)|Set-Content -LiteralPath(Join-Path $StateRoot 'state.json') -Encoding UTF8}
function Invoke-Logged([string]$Exe,[string[]]$CommandArgs,[string]$Work,[string]$Name){
  Section $Name
  Log "cwd: $Work"
  Log "exe: $Exe"
  Log "args: $($CommandArgs -join ' ')"
  Push-Location $Work
  try{
    if($VerboseLogs){& $Exe @CommandArgs 2>&1|Tee-Object -FilePath $Log -Append|Write-Host}
    else{& $Exe @CommandArgs 2>&1|ForEach-Object{Add-Content -LiteralPath $Log -Value([string]$_)-Encoding UTF8;Write-Host $_}}
    $code=$LASTEXITCODE
    Log "exit code: $code"
    if($code -ne 0){Fail "$Name failed with exit code $code."}
  }finally{Pop-Location}
}
function Python-Path{
  foreach($x in @('python','python3')){if(Command-Exists $x){return(Get-Command $x).Source}}
  return $null
}
function Flutter-Path{
  if(Command-Exists 'flutter'){return(Get-Command flutter).Source}
  $local=Join-Path $ToolRoot 'flutter/bin/flutter.bat'
  if(Test-Path $local){return $local}
  return $null
}
function Java-Path{if(Command-Exists 'java'){return(Get-Command java).Source};return $null}
function Winget-Path{if(Command-Exists 'winget'){return(Get-Command winget).Source};return $null}
function Android-Sdk{
  $c=@()
  if($env:ANDROID_HOME){$c+=$env:ANDROID_HOME}
  if($env:ANDROID_SDK_ROOT){$c+=$env:ANDROID_SDK_ROOT}
  if($env:LOCALAPPDATA){$c+=Join-Path $env:LOCALAPPDATA 'Android/Sdk'}
  foreach($p in($c|Select-Object -Unique)){if($p -and(Test-Path $p)){return $p}}
  return $null
}
function Node-Version{if(Command-Exists node){return((node --version 2>&1)|Select-Object -First 1).ToString().Trim()};return ''}
function Npm-Version{if(Command-Exists npm){return((npm --version 2>&1)|Select-Object -First 1).ToString().Trim()};return ''}
function Python-Version{$p=Python-Path;if($p){return((& $p --version 2>&1)|Select-Object -First 1).ToString().Trim()};return ''}
function Flutter-Version{$f=Flutter-Path;if($f){return((& $f --version 2>&1)|Select-Object -First 1).ToString().Trim()};return ''}

function Check-Project{
  Section 'Project files'
  $required=@(
    'README.md','VERSION','.env.example','backend/requirements.txt','backend/app','backend/tests',
    'frontend/package.json','frontend/src','frontend/index.html','frontend/tsconfig.json',
    'apps/hamraz_admin_web/package.json','apps/hamraz_admin_web/src',
    'apps/hamraz_desktop/package.json','apps/hamraz_desktop/src/main.cjs','apps/hamraz_desktop/electron-builder.yml',
    'apps/hamraz_flutter/pubspec.yaml','apps/hamraz_flutter/lib/main.dart','apps/hamraz_flutter/android/gradlew.bat',
    'docker-compose.yml','docker-compose.full.yml','docker-compose.selfhosted.yml',
    'scripts/release_gate.py','scripts/security_scan.py','scripts/audit_runtime_wiring.py'
  )
  $missing=0
  foreach($r in $required){if(Has-File $r){Ok "present: $r"}else{Warn "missing: $r";$missing++}}
  if($missing -gt 0){Fail "Project structure is incomplete: $missing required paths missing."}
}
function Check-Lockfiles{
  Section 'Dependency lockfiles'
  foreach($d in @('frontend','apps/hamraz_admin_web','apps/hamraz_desktop')){
    $r="$d/package-lock.json"
    if(Has-File $r){Ok "present: $r"}else{Warn "missing: $r (local npm install fallback will be used; strict release should commit a real lockfile)"}
  }
}
function Check-SuspiciousFiles{
  Section 'Generated/source hygiene'
  $excluded='\\(node_modules|\.venv|\.git|dist|build|release|\.hamraz-oneclick)\\'
  $bad=0
  Get-ChildItem -LiteralPath $Root -Recurse -File|Where-Object{$_.FullName -notmatch $excluded}|ForEach-Object{
    try{
      $t=[IO.File]::ReadAllText($_.FullName)
      if($t.Contains("`0")){Warn "NUL byte: $($_.FullName)";$bad++}
    }catch{}
  }
  if($bad -gt 0){Fail "Source hygiene found $bad invalid files."};Ok 'source text hygiene passed.'
}
function Backend-Venv([switch]$Install){
  $p=Python-Path;if(-not$p){Fail 'Python 3.11+ is required.'}
  $venv=Join-Root '.venv';$vp=Join-Path $venv 'Scripts/python.exe'
  if(-not(Test-Path $vp)){Invoke-Logged $p @('-m','venv','.venv') $Root 'Create Python venv'}
  if($Install){Invoke-Logged $vp @('-m','pip','install','--upgrade','pip') $Root 'Upgrade pip';Invoke-Logged $vp @('-m','pip','install','-r','backend/requirements.txt') $Root 'Install backend dependencies';Invoke-Logged $vp @('-m','pip','install','pytest') $Root 'Install pytest'}
  return $vp
}
function Npm-Install([string]$Dir){
  Require 'Node.js' 'node';Require 'npm' 'npm'
  $w=Join-Root $Dir
  if(Has-File "$Dir/package-lock.json"){Invoke-Logged 'npm' @('ci','--no-audit','--no-fund') $w "npm ci: $Dir"}
  else{Invoke-Logged 'npm' @('install','--no-audit','--no-fund') $w "npm install: $Dir"}
}
function Set-Api{
  if($ApiUrl){$env:HAMRAZ_RELEASE_API_URL=$ApiUrl}
  elseif(-not $env:HAMRAZ_RELEASE_API_URL){$env:HAMRAZ_RELEASE_API_URL='http://127.0.0.1:8000'}
  Log "API URL: $env:HAMRAZ_RELEASE_API_URL"
}
function Build-Web{
  Npm-Install 'frontend'
  Invoke-Logged 'npm' @('run','build') (Join-Root 'frontend') 'Build Web'
  $index=Join-Root 'frontend/dist/index.html';if(-not(Test-Path $index)){Fail 'Web build did not produce frontend/dist/index.html.'}
  $dst=Join-Root "release/web-$RunId";if(Test-Path $dst){Remove-Item $dst -Recurse -Force};Copy-Item (Join-Root 'frontend/dist') $dst -Recurse -Force;Ok "web output: $dst";return $dst
}
function Build-Admin{
  Npm-Install 'apps/hamraz_admin_web'
  Invoke-Logged 'npm' @('run','build') (Join-Root 'apps/hamraz_admin_web') 'Build Admin Web'
  $dist=Join-Root 'apps/hamraz_admin_web/dist';if(-not(Test-Path $dist)){Fail 'Admin dist was not produced.'}
  $dst=Join-Root "release/admin-web-$RunId";if(Test-Path $dst){Remove-Item $dst -Recurse -Force};Copy-Item $dist $dst -Recurse -Force;Ok "admin web output: $dst";return $dst
}
function Build-Windows{
  Require 'Node.js' 'node';Require 'npm' 'npm';Require 'Python' 'python'
  Build-Web|Out-Null
  $desktop=Join-Root 'apps/hamraz_desktop';$renderer=Join-Path $desktop 'frontend-dist';if(Test-Path $renderer){Remove-Item $renderer -Recurse -Force};Copy-Item (Join-Root 'frontend/dist') $renderer -Recurse -Force
  $py=Backend-Venv -Install
  if(-not(Command-Exists pyinstaller)){Invoke-Logged $py @('-m','pip','install','pyinstaller') $Root 'Install PyInstaller'}
  $spec=Join-Root 'backend/HamrazServer.spec'
  if(Test-Path $spec){Invoke-Logged $py @('-m','PyInstaller','--noconfirm','--clean','HamrazServer.spec') (Join-Root 'backend') 'Package local backend server'}
  else{Warn 'HamrazServer.spec missing; desktop local-server bundling will be limited.'}
  $server=Join-Root 'backend/dist/HamrazServer';if(-not(Test-Path (Join-Path $server 'HamrazServer.exe'))){Fail 'Backend Windows executable was not produced.'};$bundle=Join-Path $desktop 'backend-dist';if(Test-Path $bundle){Remove-Item $bundle -Recurse -Force};Copy-Item $server $bundle -Recurse -Force
  Npm-Install 'apps/hamraz_desktop'
  Invoke-Logged 'npm' @('run','package') $desktop 'Package Windows EXE'
  $dd=Join-Path $desktop 'dist';if(-not(Test-Path $dd)){Fail 'Electron dist folder missing after package.'}
  $exes=@(Get-ChildItem $dd -Filter '*.exe' -File -ErrorAction SilentlyContinue);if($exes.Count -lt 2){Fail 'Expected both Windows NSIS installer and portable EXE outputs.'}
  foreach($e in $exes){Copy-Item $e.FullName (Join-Path $Release $e.Name) -Force;Ok "EXE: $($e.Name)"}
  $version=Read-Version (Join-Root 'VERSION');$setup=Join-Path $Release "Hamraz-$version-Setup-x64.exe";$portable=Join-Path $Release "Hamraz-$version-Portable-x64.exe"
  if(-not(Test-Path $setup) -or -not(Test-Path $portable)){Fail "Expected versioned Windows artifacts missing. Found: $((Get-ChildItem $Release -Filter '*.exe' -File|Select-Object -ExpandProperty Name)-join ', ')"}
  return $exes
}
function Build-Android{
  Set-Api
  if($env:HAMRAZ_RELEASE_API_URL -notmatch '^https://'){Fail 'Android release builds require an HTTPS API URL. Pass -ApiUrl https://...'}
  $f=Flutter-Path;if(-not$f){Fail 'Flutter is unavailable. Run -Target Install or install Flutter stable.'}
  if(-not(Java-Path)){Fail 'Java/JDK is unavailable. Install a supported JDK and reopen VS Code.'}
  $sdk=Android-Sdk;if($sdk){Log "Android SDK: $sdk"}else{Warn 'ANDROID_HOME/ANDROID_SDK_ROOT not detected; Flutter may still locate the SDK.'}
  $mobile=Join-Root 'apps/hamraz_flutter'
  Invoke-Logged $f @('doctor','-v') $mobile 'Flutter doctor'
  Invoke-Logged $f @('pub','get') $mobile 'Flutter packages'
  Invoke-Logged $f @('analyze') $mobile 'Flutter analyze'
  Invoke-Logged $f @('test') $mobile 'Flutter tests'
  $define="API_URL=$env:HAMRAZ_RELEASE_API_URL"
  Invoke-Logged $f @('build','apk','--release','--dart-define',$define) $mobile 'Build Android APK'
  Invoke-Logged $f @('build','appbundle','--release','--dart-define',$define) $mobile 'Build Android AAB'
  $apk=Join-Root 'apps/hamraz_flutter/build/app/outputs/flutter-apk/app-release.apk';$aab=Join-Root 'apps/hamraz_flutter/build/app/outputs/bundle/release/app-release.aab'
  if(-not(Test-Path $apk)){Fail 'APK was not produced.'};if(-not(Test-Path $aab)){Fail 'AAB was not produced.'}
  Copy-Item $apk (Join-Path $Release 'Hamraz.apk') -Force;Copy-Item $aab (Join-Path $Release 'Hamraz.aab') -Force;Ok 'APK and AAB copied to release/';return @($apk,$aab)
}
function Verify-Backend{
  $py=Backend-Venv
  Invoke-Logged $py @('-m','compileall','-q','backend/app') $Root 'Compile backend'
  $env:PYTHONPATH=Join-Root 'backend'
  Invoke-Logged $py @('-m','pytest','-q','backend/tests') $Root 'Backend tests'
}
function Verify-Static{
  Validate-PowerShellSyntax;Validate-LocalStructure
  $py=Backend-Venv
  foreach($rel in @('scripts_release_check.py','scripts/release_gate.py','scripts/security_scan.py','scripts/release_endpoint_audit.py','scripts/audit_runtime_wiring.py')){
    $p=Join-Root $rel;if(Test-Path $p){Invoke-Logged $py @($p) $Root "Static check: $rel"}else{Warn "missing verification script: $rel"}
  }
}
function Validate-PowerShellSyntax{
  $tokens=$null;$errors=$null
  [void][System.Management.Automation.Language.Parser]::ParseFile($MyInvocation.MyCommand.Path,[ref]$tokens,[ref]$errors)
  if($errors -and $errors.Count -gt 0){$msg=($errors|ForEach-Object { $_.Message }) -join '; ';Fail "PowerShell parser found errors: $msg"}
  Ok 'PowerShell syntax passed.'
}
function Validate-LocalStructure{
  $critical=@('backend/run_server.py','backend/HamrazServer.spec','apps/hamraz_flutter/android/settings.gradle.kts','apps/hamraz_flutter/android/build.gradle.kts','apps/hamraz_flutter/android/app/build.gradle.kts')
  foreach($r in $critical){if(-not(Has-File $r)){Fail "Critical file missing: $r"}}
  $badRefs=@('HAMRAZ_ONE_CLICK_BUILD.ps1')
  foreach($r in $badRefs){if(-not(Has-File $r)){Fail "Critical builder file missing: $r"}}
  Ok 'Critical source structure passed.'
}
function Doctor{
  Section 'HAMRAZ DOCTOR'
  Validate-PowerShellSyntax
  Check-Project;Check-Lockfiles;Check-SuspiciousFiles
  $checks=@(
    @('Python','python'),@('Node.js','node'),@('npm','npm'),@('Git','git'),@('Java','java'),@('Flutter','flutter'),@('Docker','docker'),@('Winget','winget')
  )
  foreach($c in $checks){if(Command-Exists $c[1]){Ok "$($c[0]): available"}else{Warn "$($c[0]): missing"}}
  if(Flutter-Path){Ok "Flutter: available (PATH or bundled tool cache)"}else{Warn 'Flutter: missing'}
  if(Android-Sdk){Ok "Android SDK: detected"}else{Warn 'Android SDK: not detected in standard locations'}
  Log "Version=$((Read-Version (Join-Root 'VERSION'))), Node=$(Node-Version), npm=$(Npm-Version), Python=$(Python-Version), Flutter=$(Flutter-Version)"
  Ok "Doctor log: $Log"
}
function Refresh-ProcessPath{
  $machine=[Environment]::GetEnvironmentVariable('Path','Machine')
  $user=[Environment]::GetEnvironmentVariable('Path','User')
  $parts=@($machine,$user) | Where-Object { $_ -and $_.Trim() }
  if($parts.Count -gt 0){$env:Path=($parts -join ';')}
}
function Winget-Install([string]$Id,[string]$Name){
  $w=Winget-Path
  if(-not $w){Warn "winget unavailable: $Name";return}
  try{
    Invoke-Logged $w @('install','--id',$Id,'--exact','--silent','--accept-package-agreements','--accept-source-agreements') $Root "Install $Name"
    Refresh-ProcessPath
  }catch{Warn $_.Exception.Message}
}
function Install-Tools{
  Section 'INSTALL / PREPARE'
  if(-not(Command-Exists git)){Winget-Install 'Git.Git' 'Git'}
  if(-not(Command-Exists node)){Winget-Install 'OpenJS.NodeJS.LTS' 'Node.js LTS'}
  if(-not(Command-Exists python)){Winget-Install 'Python.Python.3.13' 'Python 3.13'}
  if(-not(Command-Exists java)){Winget-Install 'Microsoft.OpenJDK.21' 'OpenJDK 21'}
  if(-not(Android-Sdk)){Winget-Install 'Google.AndroidStudio' 'Android Studio'}
  Refresh-ProcessPath
  if(-not(Command-Exists flutter)){
    Require 'Git' 'git'
    $dest=Join-Path $ToolRoot 'flutter'
    if(-not(Test-Path $dest)){Invoke-Logged 'git' @('clone','--depth','1','--branch','stable','https://github.com/flutter/flutter.git',$dest) $ToolRoot 'Download Flutter stable'}
  }
  Doctor
}
function Clean{
  Section 'CLEAN'
  $generated=@('frontend/dist','apps/hamraz_admin_web/dist','apps/hamraz_desktop/dist','apps/hamraz_desktop/frontend-dist','apps/hamraz_desktop/backend-dist','apps/hamraz_flutter/build','backend/build','backend/dist','.hamraz-oneclick')
  foreach($r in $generated){$p=Join-Root $r;if(Test-Path $p){Remove-Item $p -Recurse -Force;Ok "removed: $r"}}
  if(-not$KeepBuilds -and(Test-Path $Release)){Get-ChildItem $Release -Force|Remove-Item -Recurse -Force;Ok 'release/ cleared'}
}
function Hash-Releases{
  Ensure-Dir $Release
  $files=@(Get-ChildItem -LiteralPath $Release -File -ErrorAction SilentlyContinue | Where-Object { $_.Extension -in @('.exe','.apk','.aab','.zip') })
  $lines=@()
  foreach($f in $files){
    $hash=(Get-FileHash -LiteralPath $f.FullName -Algorithm SHA256).Hash.ToLowerInvariant()
    $lines += ('{0}  {1}' -f $hash,$f.Name)
  }
  $path=Join-Path $Release "SHA256SUMS-$RunId.txt"
  $lines | Set-Content -LiteralPath $path -Encoding UTF8
  Ok "checksums: $path"
}
function Report([string]$RequestedTarget){
  $art=@(Get-ChildItem $Release -Recurse -File -ErrorAction SilentlyContinue|Where-Object{$_.Extension -in @('.exe','.apk','.aab')})|ForEach-Object{[ordered]@{name=$_.Name;path=$_.FullName;bytes=$_.Length;sha256=(Get-FileHash $_.FullName -Algorithm SHA256).Hash.ToLowerInvariant()}}
  $r=[ordered]@{timestamp=(Get-Date).ToString('o');target=$RequestedTarget;version=(Read-Version (Join-Root 'VERSION'));node=(Node-Version);npm=(Npm-Version);python=(Python-Version);flutter=(Flutter-Version);android_sdk=(Android-Sdk);api_url=$env:HAMRAZ_RELEASE_API_URL;artifacts=$art;log=$Log}
  ($r|ConvertTo-Json -Depth 12)|Set-Content $Report -Encoding UTF8;Ok "build report: $Report"
}
function Menu{
  Section 'HAMRAZ MENU'
  Write-Host '1  Doctor'
  Write-Host '2  Install / prepare tools'
  Write-Host '3  Verify source/backend'
  Write-Host '4  Build Web'
  Write-Host '5  Build Windows EXE'
  Write-Host '6  Build Android APK + AAB'
  Write-Host '7  Build All available targets'
  Write-Host '8  Clean'
  Write-Host '0  Exit'
  switch(Read-Host 'Choose'){'1'{return 'Doctor'}'2'{return 'Install'}'3'{return 'Verify'}'4'{return 'Web'}'5'{return 'Windows'}'6'{return 'Android'}'7'{return 'All'}'8'{return 'Clean'}default{return 'Exit'}}
}
function Run([string]$T){
  if($T -eq 'Menu'){$T=Menu}
  Section "RUN TARGET: $T"
  try{
    switch($T){
      'Doctor'{Doctor}
      'Install'{if(-not$SkipInstall){Install-Tools}else{Doctor}}
      'Verify'{Check-Project;Check-SuspiciousFiles;Verify-Static;Verify-Backend}
      'Web'{Check-Project;Build-Web|Out-Null}
      'Windows'{Check-Project;Build-Windows|Out-Null}
      'Android'{Check-Project;Build-Android|Out-Null}
      'All'{
        Check-Project;Verify-Static
        $failures=@()
        foreach($stage in @(@{n='backend';a={Verify-Backend}},@{n='web';a={Build-Web|Out-Null}},@{n='admin';a={Build-Admin|Out-Null}},@{n='windows';a={Build-Windows|Out-Null}},@{n='android';a={Build-Android|Out-Null}})){
          try{& $stage.a}catch{$failures += "$($stage.n): $($_.Exception.Message)";Warn "$($stage.n) failed: $($_.Exception.Message)"}
        }
        if($failures.Count -gt 0){Fail ("One or more requested build stages failed: " + ($failures -join ' | '))}
      }
      'Clean'{Clean}
    }
    if($T -ne 'Clean'){Hash-Releases}
    Ok "target completed: $T"
  }catch{ $script:ExitCode=1;Log $_.Exception.ToString() 'ERROR' }
  finally{ Report $T;Write-State @{target=$T;timestamp=(Get-Date).ToString('o');exit_code=$ExitCode;log=$Log;release=$Release} }
  if($ExitCode -ne 0){exit $ExitCode}
}

# -----------------------------------------------------------------------------
# The extended knowledge base below is data, not fake application source.
# Each entry maps a concrete stage/tool/check to a useful local action. It gives
# the user a long, inspectable, single-file troubleshooting reference while the
# executable logic above remains compact and maintainable.
# -----------------------------------------------------------------------------
$HamrazKnowledge=@(
  @{Category='bootstrap';Tool='PowerShell execution policy';Check='execution blocked';Fix='Run the script from an elevated or permitted PowerShell session: Set-ExecutionPolicy -Scope CurrentUser RemoteSigned';Command='Set-ExecutionPolicy -Scope CurrentUser RemoteSigned'}
  @{Category='bootstrap';Tool='VS Code terminal';Check='wrong working directory';Fix='Open the Hamraz root folder before running the script; the script resolves its own root from this file.';Command='Get-Location'}
  @{Category='python';Tool='python';Check='missing';Fix='Install Python 3.11+ and reopen VS Code so PATH refreshes.';Command='python --version'}
  @{Category='python';Tool='venv';Check='creation';Fix='Delete only the local .venv if corrupted, then rerun Install.';Command='python -m venv .venv'}
  @{Category='python';Tool='pip';Check='network unavailable';Fix='Check corporate proxy/DNS/firewall and rerun; do not replace real dependencies with mocks.';Command='python -m pip install -r backend/requirements.txt'}
  @{Category='python';Tool='pytest';Check='missing';Fix='The script installs pytest into .venv during Install/Windows.';Command='python -m pip install pytest'}
  @{Category='node';Tool='node';Check='missing';Fix='Install Node.js LTS and reopen VS Code.';Command='node --version'}
  @{Category='node';Tool='npm';Check='missing';Fix='Install Node.js LTS; npm ships with Node.js.';Command='npm --version'}
  @{Category='node';Tool='lockfile';Check='missing';Fix='For local work npm install is allowed; for strict release commit a real package-lock.json.';Command='npm install --no-audit --no-fund'}
  @{Category='web';Tool='TypeScript';Check='compile error';Fix='Run the Web target alone to expose the first compiler diagnostic and keep the log.';Command='npm run build'}
  @{Category='web';Tool='Vite';Check='dist missing';Fix='Inspect the preceding npm build log; the script stops rather than inventing dist/index.html.';Command='npm run build'}
  @{Category='admin';Tool='Vite';Check='dist missing';Fix='Run Admin build alone and inspect npm output.';Command='npm run build'}
  @{Category='desktop';Tool='Electron';Check='missing';Fix='Install Node.js LTS, npm install dependencies, then rerun Windows.';Command='npm install --no-audit --no-fund'}
  @{Category='desktop';Tool='electron-builder';Check='EXE missing';Fix='Inspect apps/hamraz_desktop/package.json and electron-builder output; native packaging requires Windows.';Command='npm run package'}
  @{Category='desktop';Tool='PyInstaller';Check='backend bundle missing';Fix='The script installs PyInstaller into .venv and packages backend/HamrazServer.spec when present.';Command='python -m PyInstaller --noconfirm --clean HamrazServer.spec'}
