function Knowledge-Search([string]$Text){
  $hits=@($HamrazKnowledge|Where-Object{($_.Tool+' '+$_.Check+' '+$_.Fix+' '+$_.Command) -match [regex]::Escape($Text)})
  if($hits.Count -eq 0){Write-Host 'No exact catalog hit; run Doctor and inspect the latest log.' -ForegroundColor Yellow;return}
  $hits|Select-Object -First 25|ForEach-Object{Write-Host "[$($_.Category)] $($_.Tool) / $($_.Check) -> $($_.Fix)";Write-Host "  $($_.Command)"}
}
Initialize-Runtime
Run $Target
